using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: discriminator property renamed from "Discriminator" to "$type".
        // Opt back in to the old name so existing 500K documents remain readable without migration.
        modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");

        // EF Core 9 breaking change: id format changed from "EntityType|Key" to just "Key".
        // Opt back in to the old format so existing documents with "Product|123" ids are found.
        modelBuilder.Entity<Product>().HasPartitionKey(p => p.Id);
        modelBuilder.Entity<Product>().Property(p => p.Id)
            .HasJsonPropertyName("id")
            .HasValueGenerator<LegacyCosmosIdGenerator>();

        // EF Core 9 breaking change: sync I/O now throws by default.
        // Either switch to async APIs or set this in OnConfiguring (see below).

        modelBuilder.Entity<Product>().ToContainer("Products");
    }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // EF Core 9 removed HasIndex for Cosmos (not supported); build was already a no-op warning.
        // Sync I/O opt-in — needed until ToList() calls are migrated to ToListAsync().
        optionsBuilder.UseCosmos("AccountEndpoint=...;AccountKey=...", "MyDatabase",
            cosmosOptions => { })
            .ConfigureWarnings(w => { });
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; }  }

