class CosmosQuery
{
    async Task FindProductsAsync(ProductContext ctx)
    {
        // Direct Cosmos SQL — still works because we opted back into "Discriminator" property name.
        // If we had NOT configured HasDiscriminator("Discriminator"), EF9 would write "$type" instead
        // and this query would return zero results against existing documents.
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";

        // EF Core 9 breaking change: sync I/O (ToList) throws InvalidOperationException by default.
        // Migrated to async to avoid needing the compatibility flag.
        var products = await ctx.Products.Where(p => p.Sku == "ABC").ToListAsync();
    }
}

